package com.selah.bible.data.importer

import android.content.Context
import android.database.sqlite.SQLiteDatabase
import android.net.Uri
import com.selah.bible.data.BibleVerse
import com.selah.bible.data.ImportProgress
import java.io.File
import java.io.FileOutputStream

/**
 * Instant parser for pre-built .sqlite / .db Bible databases generated by
 * tools/convert_bible.py, returning metadata + verses for combining/merging.
 */
object SqliteImporter {

    data class ParsedSqlite(
        val translationId: String,
        val code: String,
        val name: String,
        val verses: List<BibleVerse>
    )

    fun parseFromUri(
        context: Context,
        uri: Uri,
        fileName: String,
        overrideTranslationId: String? = null,
        onProgress: (ImportProgress) -> Unit
    ): ParsedSqlite {
        onProgress(ImportProgress("Opening SQLite Bible package…", 0.1f, 0))
        val tempFile = File(context.cacheDir, "import_temp.sqlite")
        try {
            context.contentResolver.openInputStream(uri)?.use { input ->
                FileOutputStream(tempFile).use { output ->
                    input.copyTo(output, bufferSize = 32 * 1024)
                }
            } ?: error("Unable to open selected SQLite file.")

            val (fallbackId, fallbackCode, fallbackName) = BibleTextParser.inferTranslationMeta(fileName)
            var translationId = fallbackId
            var code = fallbackCode
            var name = fallbackName
            val verses = ArrayList<BibleVerse>(32000)

            SQLiteDatabase.openDatabase(tempFile.absolutePath, null, SQLiteDatabase.OPEN_READONLY).use { src ->
                runCatching {
                    src.rawQuery("SELECT key, value FROM meta", null).use { c ->
                        while (c.moveToNext()) {
                            when (c.getString(0)) {
                                "id" -> translationId = c.getString(1)
                                "code" -> code = c.getString(1)
                                "name" -> name = c.getString(1)
                            }
                        }
                    }
                }

                val targetId = overrideTranslationId ?: translationId
                val query = runCatching {
                    src.rawQuery("SELECT book_id, chapter, verse, text FROM verses ORDER BY book_id, chapter, verse", null)
                }.getOrElse {
                    src.rawQuery("SELECT book, chapter, verse, text FROM verses ORDER BY book, chapter, verse", null)
                }

                query.use { c ->
                    while (c.moveToNext()) {
                        val b = c.getInt(0)
                        val ch = c.getInt(1)
                        val v = c.getInt(2)
                        val t = c.getString(3)?.trim().orEmpty()
                        if (b in 1..66 && ch >= 1 && v >= 1 && t.isNotEmpty()) {
                            verses.add(BibleVerse(targetId, b, ch, v, t))
                        }
                    }
                }

                return ParsedSqlite(targetId, code, name, verses)
            }
        } finally {
            tempFile.delete()
        }
    }
}
